using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using System.Security.Cryptography;
using System.Text;
using System.Xml.Linq;
namespace Atlas;
public static class Analyzer {
 public static string Id(ISymbol symbol){if(symbol is IMethodSymbol method)symbol=(method.ReducedFrom??method).OriginalDefinition;else symbol=symbol.OriginalDefinition;return (symbol.ContainingAssembly?.Identity.Name??"unresolved")+":"+(symbol.GetDocumentationCommentId()??symbol.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat));}
 static SourceLocation Location(SyntaxNode node){var s=node.GetLocation().GetLineSpan();return new(s.Path,s.StartLinePosition.Line+1,s.EndLinePosition.Line+1);}
 static string Doc(ISymbol symbol){try{var xml=symbol.GetDocumentationCommentXml();return string.IsNullOrWhiteSpace(xml)?"":string.Join(" ",XElement.Parse(xml).Element("summary")?.Value.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries)??[]);}catch{return "";}}
 public static async Task<Snapshot> Analyze(Solution solution,string path,List<Issue> workspaceIssues,CancellationToken ct,(GitInfo Info,Dictionary<string,string> States)? comparison=null){
  var root=Path.GetDirectoryName(path)!;var (git,states)=comparison??await GitReader.Read(root);var classes=new Dictionary<string,ClassNode>();var methodOwners=new Dictionary<string,string>();var bodies=new List<(SyntaxNode Node,SemanticModel Model,string Method,string Class)>();var rawCalls=new List<(string Source,string Target,string SourceClass,string Kind,string Dispatch,int Order)>();var bases=new List<(string From,string To,string Kind)>();var classSymbols=new Dictionary<string,INamedTypeSymbol>();var issues=new List<Issue>(workspaceIssues);int unresolved=0;
  var projectFacts=ProjectFacts.Read(solution,path);var uses=new HashSet<(string From,string To)>();
  foreach(var project in solution.Projects.Where(p=>p.Language==LanguageNames.CSharp)){
   var compilation=await project.GetCompilationAsync(ct);if(compilation==null)continue;
   foreach(var d in compilation.GetDiagnostics(ct).Where(d=>d.Severity==DiagnosticSeverity.Error).Take(60)){var loc=d.Location.GetLineSpan();issues.Add(new("error",d.GetMessage(),loc.Path,loc.StartLinePosition.Line+1));}
   foreach(var document in project.Documents){ct.ThrowIfCancellationRequested();if(document.FilePath==null||document.FilePath.Split(Path.DirectorySeparatorChar).Any(p=>p is "obj" or "bin"))continue;var tree=await document.GetSyntaxRootAsync(ct);var model=await document.GetSemanticModelAsync(ct);if(tree==null||model==null)continue;var text=await document.GetTextAsync(ct);var status=states.GetValueOrDefault(GitReader.Canonical(document.FilePath),"existing");
    foreach(var declaration in tree.DescendantNodes().OfType<BaseTypeDeclarationSyntax>()){
     if(model.GetDeclaredSymbol(declaration,ct) is not INamedTypeSymbol symbol)continue;var cid=Id(symbol);classSymbols[cid]=symbol;var location=Location(declaration);var group=symbol.ContainingNamespace.IsGlobalNamespace?project.Name:symbol.ContainingNamespace.ToDisplayString();
     var fields=declaration is TypeDeclarationSyntax td?string.Join("\n",td.Members.Where(m=>m is FieldDeclarationSyntax or PropertyDeclarationSyntax or EventFieldDeclarationSyntax).Select(m=>m.ToString())):"";
     if(!classes.TryGetValue(cid,out var c)){c=new(cid,symbol.Name,symbol.ToDisplayString(),symbol.TypeKind.ToString().ToLowerInvariant(),group,project.Name,declaration.ToString(),fields,text.Lines.Count,[location],[],status){ProjectId=ProjectFacts.Key(project,root),ContainingTypeId=symbol.ContainingType is {} outer?Id(outer):null,Accessibility=symbol.DeclaredAccessibility.ToString(),Generated=document.FilePath.EndsWith(".g.cs")||document.FilePath.EndsWith(".generated.cs")||text.ToString().Take(300).ToArray() is var prefix&&new string(prefix).Contains("<auto-generated")};classes[cid]=c;
      if(symbol.BaseType is {SpecialType:SpecialType.None} parent)bases.Add((cid,Id(parent),"inherits"));foreach(var iface in symbol.Interfaces)bases.Add((cid,Id(iface),"implements"));
     }else{c=c with{Code=c.Code+"\n\n"+declaration,Fields=c.Fields+"\n"+fields,Lines=c.Locations.Any(l=>l.File==location.File)?c.Lines:c.Lines+text.Lines.Count,Status=status!="existing"?status:c.Status};c.Locations.Add(location);classes[cid]=c;}
     foreach(var syntax in declaration.DescendantNodes(n=>n==declaration||n is not BaseTypeDeclarationSyntax).OfType<TypeSyntax>()){
      if(model.GetTypeInfo(syntax,ct).Type is INamedTypeSymbol referenced&&referenced.TypeKind!=TypeKind.Error&&referenced.ContainingAssembly!=null){var target=Id(referenced);if(target!=cid)uses.Add((cid,target));}
     }
     foreach(var node in declaration.DescendantNodes().Where(n=>n is BaseMethodDeclarationSyntax or AccessorDeclarationSyntax or LocalFunctionStatementSyntax)){
      if(node is AccessorDeclarationSyntax {Body:null,ExpressionBody:null})continue;
      if(model.GetDeclaredSymbol(node,ct) is not IMethodSymbol method||!SymbolEqualityComparer.Default.Equals(method.ContainingType,symbol))continue;var mid=Id(method);if(c.Methods.Any(m=>m.Id==mid))continue;
      var signature=method.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat);var name=method.MethodKind is MethodKind.Constructor or MethodKind.StaticConstructor?symbol.Name:method.Name;
      c.Methods.Add(new(mid,name,signature,method.ReturnType.ToDisplayString(SymbolDisplayFormat.MinimallyQualifiedFormat),node.ToString(),Doc(method),method.MethodKind.ToString(),Location(node),status));methodOwners[mid]=cid;bodies.Add((node,model,mid,cid));
     }
    }
   }
  }
  foreach(var body in bodies){foreach(var call in body.Node.DescendantNodes(n=>n==body.Node||n is not LocalFunctionStatementSyntax).Where(n=>n is InvocationExpressionSyntax or ObjectCreationExpressionSyntax or ImplicitObjectCreationExpressionSyntax or ConstructorInitializerSyntax)){
    // A containing method does not own invocations inside another local function.
    var owner=call.Ancestors().FirstOrDefault(n=>n is BaseMethodDeclarationSyntax or AccessorDeclarationSyntax or LocalFunctionStatementSyntax);if(owner!=body.Node)continue;
    var info=body.Model.GetSymbolInfo(call,ct);if(info.Symbol is not IMethodSymbol target){unresolved++;continue;}var dispatch=target.ContainingType?.TypeKind==TypeKind.Interface?"interface":target.IsVirtual||target.IsAbstract||target.IsOverride?"virtual":"static";
    rawCalls.Add((body.Method,Id(target),body.Class,call is InvocationExpressionSyntax?"calls":"constructs",dispatch,call.SpanStart));
   }}
  var edges=new List<GraphEdge>();foreach(var group in rawCalls.Where(c=>methodOwners.ContainsKey(c.Target)).GroupBy(c=>(c.Source,c.Target,c.Kind,c.Dispatch))){var first=group.First();edges.Add(new(first.Source+"->"+first.Target,first.Source,first.Target,first.SourceClass,methodOwners[first.Target],first.Kind,first.Dispatch,group.Count()){Order=group.Min(c=>c.Order)});}
  // Roslyn resolves explicit implementations and overloads exactly, including inherited contracts.
  var calledContracts=edges.Where(e=>e.Kind=="calls"&&e.Dispatch=="interface").Select(e=>e.Target).ToHashSet();
  foreach(var (classId,symbol) in classSymbols.Where(pair=>pair.Value.TypeKind==TypeKind.Class)){
   foreach(var iface in symbol.AllInterfaces){
    var interfaceId=Id(iface);if(!classes.ContainsKey(interfaceId))continue;
    foreach(var member in iface.GetMembers().OfType<IMethodSymbol>()){
     var contractId=Id(member);if(!calledContracts.Contains(contractId))continue;
     var implementation=symbol.FindImplementationForInterfaceMember(member) as IMethodSymbol;
     // Roslyn can return null here when the contract belongs to an open generic
     // interface from another project (for example IMessageHandler<TKey,TValue>)
     // while the class implements a closed construction of it. In that case the
     // concrete member is still unambiguous after substituting the interface.
     implementation??=symbol.GetMembers(member.Name).OfType<IMethodSymbol>()
      .FirstOrDefault(method=>method.Parameters.Length==member.Parameters.Length&&
       method.ExplicitInterfaceImplementations.Any(contract=>Id(contract)==contractId));
     implementation??=symbol.GetMembers(member.Name).OfType<IMethodSymbol>()
      .FirstOrDefault(method=>method.Parameters.Length==member.Parameters.Length);
     if(implementation is null)continue;
     var concreteId=Id(implementation);
     if(!methodOwners.ContainsKey(concreteId)){
      // A closed generic interface may return a substituted implementation symbol.
      // Resolve it back to the declared method stored in the graph.
      var declared=implementation.OriginalDefinition;
      concreteId=Id(declared);
      if(!methodOwners.ContainsKey(concreteId)){
       var candidate=classes[classId].Methods.Where(method=>method.Name==implementation.Name).Select(method=>method.Id).FirstOrDefault();
       if(candidate is not null)concreteId=candidate;
      }
     }
     if(!methodOwners.ContainsKey(concreteId)||concreteId==contractId)continue;
     var concreteClass=methodOwners[concreteId];
     var id=contractId+"->"+concreteId+":implementation";
     if(!edges.Any(e=>e.Id==id))edges.Add(new(id,contractId,concreteId,interfaceId,concreteClass,"calls","implementation",1));
    }
   }
  }
  foreach(var b in bases.Where(b=>classes.ContainsKey(b.To)))edges.Add(new(b.From+"->"+b.To+":"+b.Kind,b.From,b.To,b.From,b.To,b.Kind,"static",1));
  foreach(var u in uses.Where(u=>classes.ContainsKey(u.To)))edges.Add(new(u.From+"->"+u.To+":uses",u.From,u.To,u.From,u.To,"uses","static",1));
  var ordered=classes.Values.OrderBy(c=>c.Id).ToList();var revision=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(string.Join("",ordered.Select(c=>c.Id+c.Code+c.Status))+string.Join("",edges)+string.Join("",git.DeletedFiles)+string.Join("",issues))));
  revision=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(revision+System.Text.Json.JsonSerializer.Serialize(projectFacts))));
  return new(Path.GetFileNameWithoutExtension(path),root,path,revision,DateTimeOffset.UtcNow,ordered,edges,issues,unresolved,git){Projects=projectFacts};
 }
}
